import{_ as e,o as t,c as a,a2 as i}from"./chunks/framework.CdvW4CUT.js";const _=JSON.parse('{"title":"副本服特殊設定/機制","description":"副本服的特殊設定及特殊機制。","frontmatter":{"title":"副本服特殊設定/機制","description":"副本服的特殊設定及特殊機制。"},"headers":[],"relativePath":"dungeon/sp_setting/index.md","filePath":"dungeon/sp_setting.md"}'),o={name:"dungeon/sp_setting/index.md"};function r(n,l,s,d,c,p){return t(),a("div",null,[...l[0]||(l[0]=[i('<h1 id="特殊設定-機制" tabindex="-1">特殊設定/機制 <a class="header-anchor" href="#特殊設定-機制" aria-label="Permalink to &quot;特殊設定/機制&quot;">​</a></h1><h2 id="pvp懲罰機制" tabindex="-1">PVP懲罰機制 <a class="header-anchor" href="#pvp懲罰機制" aria-label="Permalink to &quot;PVP懲罰機制&quot;">​</a></h2><p>副本的PVP是<font color="red"><b>強制開啟</b></font>的<br> 但擊殺玩家會有相對應的懲罰機制<br> 以防止惡意影響其他玩家遊玩</p><h3 id="機制說明" tabindex="-1">機制說明 <a class="header-anchor" href="#機制說明" aria-label="Permalink to &quot;機制說明&quot;">​</a></h3><ol><li>當你擊殺玩家後，你會進入『PVP警告模式』 <ul><li>期間內再次擊殺玩家，將進入『PVP懲罰模式』</li></ul></li><li>當進入『PVP懲罰模式』後，期間內會有<b>行動限制</b><ul><li>你不能離開副本服，包含上下線/回到大廳</li><li>不可使用副本服內的任何傳送門</li></ul></li><li>在『PVP懲罰模式』期間內違反了行動限制，會受到<strong>扣除副本幣</strong>的懲罰 <ul><li>若身上已無副本幣可罰款，違反的當下將會<font color="red"><b>立即死亡並噴裝</b></font></li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">備註</p><p>若你認為機制判定時間有誤請輸入<code>/pvpmode</code>由系統自動除錯</p></div><h3 id="抽獎" tabindex="-1">抽獎 <a class="header-anchor" href="#抽獎" aria-label="Permalink to &quot;抽獎&quot;">​</a></h3><p>玩家受到懲罰所扣除的副本幣及物品會進到副本獎池中 提供給玩家抽獎</p><ul><li>副本服人數高於一定數量時，會觸發抽獎 <ul><li>獎品為獎池中一定比例的副本幣</li></ul></li><li>每次抽獎會有一定機率觸發追加抽獎 <ul><li>獎品為獎池中一定數量的裝備與物品</li></ul></li></ul>',9)])])}const h=e(o,[["render",r]]);export{_ as __pageData,h as default};
